output_text:
[
  {
    "id": "no_carts_in_single_file_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles, which are narrow pedestrian-only canyons between shelves.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileShelfAisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "detach_cart_only_at_aisle_mouth",
    "text": "A cart may be left behind only at designated wide aisle-mouth parking cells before entering a narrow pedestrian shelf aisle.",
    "abstraction": {
      "state_properties": {
        "aisleMouthParkingCell": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "detachCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "detachCart",
          {
            "not": "aisleMouthParkingCell"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "Whenever a shopper parks a cart to walk into a pedestrian-only aisle, they are obliged to return and pick the cart back up before leaving.",
    "abstraction": {
      "state_properties": {
        "aisleMouthParkingCell": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCartAtMouth": {
          "pre": {
            "and": [
              "aisleMouthParkingCell",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCartAtMouth": {
          "pre": {
            "and": [
              "aisleMouthParkingCell",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCartAtMouth",
      "discharge": "retrieveCartAtMouth"
    }
  },
  {
    "id": "no_cartless_open_floor_travel",
    "text": "After taking a cart, shoppers may walk without it only in pedestrian shelf aisles or at their aisle-mouth parking cells, not through the open store floor.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "aisleMouthParkingCell": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartStartArea": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "allowedCartlessArea": {
          "or": [
            "singleFileShelfAisle",
            "aisleMouthParkingCell",
            "cartStartArea"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "allowedCartlessArea"
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_at_open_shelf_faces",
    "text": "At open shelf faces in cart-accessible aisles, shoppers are prohibited from interacting with shelves unless they have their cart.",
    "abstraction": {
      "state_properties": {
        "openShelfFace": {
          "and": [
            "adjShelf",
            {
              "ge": [
                "freeWidthH",
                2
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "openShelfFace",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "single_file_shelf_service_without_cart",
    "text": "Shelf interactions inside single-file aisles must be done without a shopping cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfFace": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileShelfFace",
          "INTERACT",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "eastbound_cart_flow_in_wide_aisles",
    "text": "Carts in wide horizontal aisles must follow the store's one-way eastbound traffic flow and may not be pushed west.",
    "abstraction": {
      "state_properties": {
        "wideHorizontalCartAisle": {
          "and": [
            "hasCart",
            {
              "ge": [
                "freeWidthH",
                6
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "wideHorizontalCartAisle",
          "W"
        ]
      }
    }
  },
  {
    "id": "leave_shelf_stops_with_cart_flow",
    "text": "When stopped with a cart at a shelf face, shoppers may not leave by turning back against the aisle flow or by moving toward the shelf.",
    "abstraction": {
      "state_properties": {
        "cartShelfFace": {
          "and": [
            "hasCart",
            "adjShelf",
            {
              "ge": [
                "freeWidthH",
                2
              ]
            }
          ]
        },
        "northShelfFace": {
          "and": [
            "cartShelfFace",
            "shelfN"
          ]
        },
        "southShelfFace": {
          "and": [
            "cartShelfFace",
            "shelfS"
          ]
        },
        "eastShelfFace": {
          "and": [
            "cartShelfFace",
            "shelfE"
          ]
        },
        "westShelfFace": {
          "and": [
            "cartShelfFace",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          {
            "and": [
              "northShelfFace",
              {
                "or": [
                  "N",
                  "W"
                ]
              }
            ]
          },
          {
            "and": [
              "southShelfFace",
              {
                "or": [
                  "S",
                  "W"
                ]
              }
            ]
          },
          {
            "and": [
              "eastShelfFace",
              {
                "or": [
                  "E",
                  "W"
                ]
              }
            ]
          },
          {
            "and": [
              "westShelfFace",
              "W"
            ]
          }
        ]
      }
    }
  }
]
